export function translateText(value: string, locale: Locale): string {
  if (locale === "en" || !value.trim()) return value;
  const leading = value.match(/^\s*/)?.[0] ?? "";
  const trailing = value.match(/\s*$/)?.[0] ?? "";
  const normalized = value.trim();
  return `${leading}${finalCopy[locale][normalized] ?? dictionaries[locale][normalized] ?? normalized}${trailing}`;
}

const translatedAttributes = new Set(["alt", "aria-label", "title"]);

function translateNode(node: ReactNode, locale: Locale): ReactNode {
  if (typeof node === "string") return translateText(node, locale);
  if (typeof node === "number" || node == null || typeof node === "boolean") return node;
  if (Array.isArray(node)) return node.map((item) => translateNode(item, locale));
  if (!isValidElement(node)) return node;

  const element = node as ReactElement<Record<string, unknown>>;
  const props: Record<string, unknown> = {};
  Object.entries(element.props).forEach(([key, value]) => {
    if (key === "children") {
      props.children = Children.map(value as ReactNode, (child) => translateNode(child, locale));
    } else if (translatedAttributes.has(key) && typeof value === "string") {
      props[key] = translateText(value, locale);
    } else {
      props[key] = value;
    }
  });
  return cloneElement(element, props);
}

export function Translated({ children }: { children: ReactNode }) {
  const locale = useContext(LanguageContext);
  return <>{translateNode(children, locale)}</>;
}
